/**
 * ToolComparisonTable Component
 * 
 * A comparison table for highlighting tool differences.
 */

"use client";

import { ToolMetadata } from '@/lib/tools';
import { Star, Check, X, Minus } from 'lucide-react';
import { Rating } from '@/components/Rating';
import Link from 'next/link';

interface ComparisonFeature {
  label: string;
  getValue: (tool: ToolMetadata) => string | boolean | number;
  highlight?: boolean;
}

interface ToolComparisonTableProps {
  tools: ToolMetadata[];
  title?: string;
  features?: ComparisonFeature[];
  showRating?: boolean;
  showPrice?: boolean;
  highlightTool?: string; // slug of tool to highlight
  className?: string;
}

export function ToolComparisonTable({
  tools,
  title = 'Tool Comparison',
  features = [],
  showRating = true,
  showPrice = true,
  highlightTool,
  className = '',
}: ToolComparisonTableProps) {
  const defaultFeatures: ComparisonFeature[] = [
    {
      label: 'Rating',
      getValue: (tool) => tool.rating,
      highlight: true,
    },
    {
      label: 'Category',
      getValue: (tool) => tool.category,
    },
    {
      label: 'Free Tier',
      getValue: (tool) => tool.pricing === 'free' || tool.pricing === 'freemium',
    },
    {
      label: 'Commercial Use',
      getValue: (tool) => true, // Assume commercial use available
    },
    {
      label: 'Easy to Use',
      getValue: (tool) => tool.rating >= 4.5 ? 'Excellent' : tool.rating >= 4 ? 'Good' : 'Fair',
    },
  ];

  const allFeatures = features.length > 0 ? features : defaultFeatures;

  const renderValue = (value: string | boolean | number, isHighlight: boolean = false) => {
    if (typeof value === 'boolean') {
      return value ? (
        <Check className="h-5 w-5 text-green-500 mx-auto" />
      ) : (
        <X className="h-5 w-5 text-red-500 mx-auto" />
      );
    }

    if (typeof value === 'number' && isHighlight) {
      return (
        <div className="flex items-center justify-center gap-1">
          <span className="font-bold">{value.toFixed(1)}</span>
          <Star className="h-4 w-4 text-yellow-500 fill-yellow-500" />
        </div>
      );
    }

    return <span className="text-sm">{value}</span>;
  };

  return (
    <div className={`overflow-x-auto rounded-xl border border-zinc-200 dark:border-zinc-800 ${className}`}>
      <table className="w-full min-w-[600px]">
        <thead>
          <tr className="bg-zinc-50 dark:bg-zinc-900/50">
            <th className="text-left p-4 font-semibold text-zinc-900 dark:text-white">
              {title}
            </th>
            {tools.map((tool) => (
              <th
                key={tool.slug}
                className={`text-center p-4 font-semibold ${
                  highlightTool === tool.slug
                    ? 'bg-purple-50 dark:bg-purple-900/20 text-purple-700 dark:text-purple-300'
                    : 'text-zinc-900 dark:text-white'
                }`}
              >
                <div className="flex flex-col items-center gap-2">
                  {tool.image && (
                    <div className="relative w-12 h-12 rounded-lg overflow-hidden">
                      <img
                        src={tool.image}
                        alt={tool.title}
                        className="object-cover w-full h-full"
                      />
                    </div>
                  )}
                  <span className="text-lg">{tool.title}</span>
                  {highlightTool === tool.slug && (
                    <span className="text-xs px-2 py-0.5 rounded-full bg-purple-100 text-purple-700 dark:bg-purple-900/50 dark:text-purple-300">
                      Top Pick
                    </span>
                  )}
                </div>
              </th>
            ))}
          </tr>
        </thead>
        <tbody className="divide-y divide-zinc-200 dark:divide-zinc-800">
          {allFeatures.map((feature, idx) => (
            <tr
              key={feature.label}
              className={idx % 2 === 0 ? 'bg-white dark:bg-zinc-950' : 'bg-zinc-50 dark:bg-zinc-900/20'}
            >
              <td className="p-4 text-sm font-medium text-zinc-700 dark:text-zinc-300">
                {feature.label}
              </td>
              {tools.map((tool) => (
                <td
                  key={tool.slug}
                  className={`p-4 text-center ${
                    highlightTool === tool.slug
                      ? 'bg-purple-50/50 dark:bg-purple-900/10'
                      : ''
                  }`}
                >
                  {renderValue(feature.getValue(tool), feature.highlight)}
                </td>
              ))}
            </tr>
          ))}
          <tr className="bg-zinc-50 dark:bg-zinc-900/50">
            <td className="p-4"></td>
            {tools.map((tool) => (
              <td key={tool.slug} className="p-4 text-center">
                <Link
                  href={`/tools/${tool.slug}`}
                  className={`inline-flex items-center justify-center px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                    highlightTool === tool.slug
                      ? 'bg-purple-600 text-white hover:bg-purple-700'
                      : 'bg-zinc-900 text-white hover:bg-zinc-700 dark:bg-white dark:text-zinc-900 dark:hover:bg-zinc-200'
                  }`}
                >
                  {highlightTool === tool.slug ? 'Try Now' : 'View Details'}
                </Link>
              </td>
            ))}
          </tr>
        </tbody>
      </table>
    </div>
  );
}

/**
 * Tool of the Week API Route
 * 
 * GET /api/tool-of-the-week - Get current Tool of the Week
 * POST /api/tool-of-the-week - Set a new Tool of the Week
 */

import { NextRequest, NextResponse } from 'next/server';
import { getAllTools, ToolMetadata } from '@/lib/tools';
import fs from 'fs';
import path from 'path';

const TOOLS_DIR = path.join(process.cwd(), 'content/tools/en');

interface ToolOfTheWeekResponse {
  tool: ToolMetadata | null;
  nextRotation?: string;
  previousTools?: Array<{ title: string; date: string }>;
}

/**
 * GET /api/tool-of-the-week
 */
export async function GET(request: NextRequest) {
  const searchParams = request.nextUrl.searchParams;
  const locale = searchParams.get('locale') || 'en';

  try {
    const tools = await getAllTools(locale);
    const currentTool = tools.find((tool) => tool.tool_of_the_week) || null;

    // Calculate next rotation (next Monday)
    const now = new Date();
    const nextMonday = new Date(now);
    nextMonday.setDate(now.getDate() + ((1 + 7 - now.getDay()) % 7 || 7));
    nextMonday.setHours(0, 0, 0, 0);

    // Get previous Tool of the Week posts if directory exists
    const postsDir = path.join(process.cwd(), 'content/posts/en/tool-of-the-week');
    let previousTools: Array<{ title: string; date: string }> = [];

    if (fs.existsSync(postsDir)) {
      const files = fs.readdirSync(postsDir).filter(f => f.endsWith('.md'));
      previousTools = files.slice(-4).map(file => {
        const filename = file.replace('tool-of-the-week-', '').replace('.md', '');
        const parts = filename.split('-');
        const date = `${parts[0]}-${parts[1]}-${parts[2]}`;
        const titleSlug = parts.slice(3).join('-');
        return {
          title: titleSlug.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' '),
          date,
        };
      });
    }

    const response: ToolOfTheWeekResponse = {
      tool: currentTool,
      nextRotation: nextMonday.toISOString(),
      previousTools: previousTools.reverse(),
    };

    return NextResponse.json(response);
  } catch (error) {
    console.error('Error fetching Tool of the Week:', error);
    return NextResponse.json(
      { error: 'Failed to fetch Tool of the Week' },
      { status: 500 }
    );
  }
}

/**
 * POST /api/tool-of-the-week
 * 
 * Body:
 * {
 *   slug: string,      // Tool slug to feature
 *   locale?: string    // Optional locale
 * }
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { slug, locale = 'en' } = body;

    if (!slug) {
      return NextResponse.json(
        { error: 'Tool slug is required' },
        { status: 400 }
      );
    }

    const tools = await getAllTools(locale);
    const toolToFeature = tools.find((tool) => tool.slug === slug);

    if (!toolToFeature) {
      return NextResponse.json(
        { error: 'Tool not found' },
        { status: 404 }
      );
    }

    // Update tool_of_the_week flag for all tools
    const toolsDir = path.join(TOOLS_DIR, '*.md');

    for (const tool of tools) {
      const toolPath = path.join(TOOLS_DIR, `${tool.slug}.md`);

      if (fs.existsSync(toolPath)) {
        let content = fs.readFileSync(toolPath, 'utf8');

        if (tool.slug === slug) {
          // Add tool_of_the_week: true if not present
          if (!content.includes('tool_of_the_week:')) {
            const yamlEnd = content.indexOf('---', 4);
            if (yamlEnd !== -1) {
              content = content.slice(0, yamlEnd) + 'tool_of_the_week: true\n' + content.slice(yamlEnd);
            }
          }
          content = content.replace(/tool_of_the_week:\s*false/g, 'tool_of_the_week: true');
          content = content.replace(/tool_of_the_week:\s*true\n/g, 'tool_of_the_week: true\n');
          // Remove duplicate tool_of_the_week lines
          const lines = content.split('\n');
          const seen = new Set();
          const deduped = lines.filter(line => {
            if (line.startsWith('tool_of_the_week:')) {
              if (seen.has('tool_of_the_week')) return false;
              seen.add('tool_of_the_week');
              return true;
            }
            return true;
          });
          content = deduped.join('\n');
        } else {
          // Remove tool_of_the_week from other tools
          content = content.replace(/tool_of_the_week:\s*true/g, 'tool_of_the_week: false');
        }

        fs.writeFileSync(toolPath, content);
      }
    }

    // Revalidate the cache
    // In a real app, you'd use revalidatePath from next/cache

    return NextResponse.json({
      success: true,
      message: `${toolToFeature.title} is now the Tool of the Week`,
      tool: toolToFeature,
    });
  } catch (error) {
    console.error('Error setting Tool of the Week:', error);
    return NextResponse.json(
      { error: 'Failed to set Tool of the Week' },
      { status: 500 }
    );
  }
}

/**
 * Tool of the Week Metrics API Route
 * 
 * GET /api/tool-of-the-week/metrics - Get performance metrics
 * POST /api/tool-of-the-week/metrics - Track a metric
 */

import { NextRequest, NextResponse } from 'next/server';
import {
  trackView,
  trackClick,
  trackConversion,
  trackSocialShare,
  getAllMetrics,
  getAggregatedMetrics,
  generatePerformanceReport,
} from '@/lib/scheduler/performance-tracker';

interface MetricPayload {
  toolSlug: string;
  metric: 'view' | 'click' | 'conversion' | 'social_share';
  platform?: 'twitter' | 'facebook' | 'linkedin' | 'reddit';
  data?: Record<string, unknown>;
}

/**
 * GET /api/tool-of-the-week/metrics
 */
export async function GET(request: NextRequest) {
  const searchParams = request.nextUrl.searchParams;
  const format = searchParams.get('format') || 'json';
  const toolSlug = searchParams.get('tool');

  try {
    if (toolSlug) {
      const metrics = getAllMetrics().find(m => m.toolSlug === toolSlug);

      if (!metrics) {
        return NextResponse.json(
          { error: 'Tool not found' },
          { status: 404 }
        );
      }

      return NextResponse.json(metrics);
    }

    const aggregated = getAggregatedMetrics();

    if (format === 'report') {
      const report = generatePerformanceReport();
      return new NextResponse(report, {
        headers: {
          'Content-Type': 'text/markdown',
        },
      });
    }

    return NextResponse.json(aggregated);
  } catch (error) {
    console.error('Error fetching metrics:', error);
    return NextResponse.json(
      { error: 'Failed to fetch metrics' },
      { status: 500 }
    );
  }
}

/**
 * POST /api/tool-of-the-week/metrics
 * 
 * Body:
 * {
 *   toolSlug: string,
 *   metric: 'view' | 'click' | 'conversion' | 'social_share',
 *   platform?: string (for social_share),
 *   data?: Record<string, unknown>
 * }
 */
export async function POST(request: NextRequest) {
  try {
    const body: MetricPayload = await request.json();
    const { toolSlug, metric, platform } = body;

    if (!toolSlug || !metric) {
      return NextResponse.json(
        { error: 'toolSlug and metric are required' },
        { status: 400 }
      );
    }

    switch (metric) {
      case 'view':
        trackView(toolSlug);
        break;
      case 'click':
        trackClick(toolSlug);
        break;
      case 'conversion':
        trackConversion(toolSlug);
        break;
      case 'social_share':
        if (platform && ['twitter', 'facebook', 'linkedin', 'reddit'].includes(platform)) {
          trackSocialShare(toolSlug, platform as 'twitter' | 'facebook' | 'linkedin' | 'reddit');
        } else {
          return NextResponse.json(
            { error: 'platform is required for social_share metric' },
            { status: 400 }
          );
        }
        break;
      default:
        return NextResponse.json(
          { error: 'Invalid metric type' },
          { status: 400 }
        );
    }

    return NextResponse.json({
      success: true,
      message: `Tracked ${metric} for ${toolSlug}`,
    });
  } catch (error) {
    console.error('Error tracking metric:', error);
    return NextResponse.json(
      { error: 'Failed to track metric' },
      { status: 500 }
    );
  }
}

/**
 * Tool of the Week Scheduler API Route
 * 
 * POST /api/tool-of-the-week/schedule - Run the scheduler to rotate Tool of the Week
 */

import { NextRequest, NextResponse } from 'next/server';
import {
  runToolOfTheWeekScheduler,
  shouldRotate,
  selectNextToolOfTheWeek,
  getCurrentToolOfTheWeek,
} from '@/lib/scheduler/tool-of-the-week-scheduler';
import { SchedulerConfig } from '@/lib/scheduler/tool-of-the-week-scheduler';

/**
 * GET /api/tool-of-the-week/schedule
 * 
 * Check scheduler status and get rotation info
 */
export async function GET(request: NextRequest) {
  const searchParams = request.nextUrl.searchParams;
  const locale = searchParams.get('locale') || 'en';

  try {
    const currentTool = await getCurrentToolOfTheWeek();
    const shouldRotateNow = shouldRotate();
    const nextTool = await selectNextToolOfTheWeek();

    // Calculate next rotation time
    const now = new Date();
    const nextMonday = new Date(now);
    nextMonday.setDate(now.getDate() + ((1 + 7 - now.getDay()) % 7 || 7));
    nextMonday.setHours(0, 0, 0, 0);

    return NextResponse.json({
      currentTool,
      shouldRotate: shouldRotateNow,
      nextRotation: nextMonday.toISOString(),
      suggestedNextTool: nextTool,
    });
  } catch (error) {
    console.error('Error checking scheduler status:', error);
    return NextResponse.json(
      { error: 'Failed to check scheduler status' },
      { status: 500 }
    );
  }
}

/**
 * POST /api/tool-of-the-week/schedule
 * 
 * Body (optional):
 * {
 *   force?: boolean,    // Force rotation even if not scheduled
 *   toolSlug?: string,  // Manually specify tool to feature
 *   locale?: string
 * }
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { force = false, toolSlug, locale = 'en' } = body;

    // If toolSlug is provided, manually set that tool
    if (toolSlug) {
      const result = await manualRotation(toolSlug, locale);
      return NextResponse.json(result);
    }

    // Otherwise run automatic scheduler
    if (!force && !shouldRotate()) {
      return NextResponse.json(
        { 
          success: false, 
          message: 'Not time for rotation. Use { force: true } to override.',
          nextRotation: calculateNextRotation(),
        },
        { status: 400 }
      );
    }

    const result = await runToolOfTheWeekScheduler({
      rotationDay: 1,
      maxToolsPerWeek: 1,
      considerCategories: true,
      minRatingThreshold: 4.0,
    });

    return NextResponse.json(result);
  } catch (error) {
    console.error('Error running scheduler:', error);
    return NextResponse.json(
      { error: 'Failed to run scheduler' },
      { status: 500 }
    );
  }
}

/**
 * Manually set a specific tool as Tool of the Week
 */
async function manualRotation(slug: string, locale: string) {
  const { getAllTools, ToolMetadata } = await import('@/lib/tools');
  const fs = await import('fs');
  const path = await import('path');

  const tools = await getAllTools(locale);
  const tool = tools.find(t => t.slug === slug);

  if (!tool) {
    return { success: false, message: 'Tool not found' };
  }

  // Update tool metadata files
  const toolsDir = path.join(process.cwd(), 'content/tools/en');

  for (const t of tools) {
    const toolPath = path.join(toolsDir, `${t.slug}.md`);

    if (fs.existsSync(toolPath)) {
      let content = fs.readFileSync(toolPath, 'utf8');

      if (t.slug === slug) {
        content = content.replace(/tool_of_the_week:\s*false/g, 'tool_of_the_week: true');
        if (!content.includes('tool_of_the_week:')) {
          const yamlEnd = content.indexOf('---', 4);
          if (yamlEnd !== -1) {
            content = content.slice(0, yamlEnd) + 'tool_of_the_week: true\n' + content.slice(yamlEnd);
          }
        }
      } else {
        content = content.replace(/tool_of_the_week:\s*true/g, 'tool_of_the_week: false');
      }

      fs.writeFileSync(toolPath, content);
    }
  }

  return {
    success: true,
    message: `${tool.title} is now the Tool of the Week (manually set)`,
    tool: tool,
  };
}

/**
 * Calculate next rotation date
 */
function calculateNextRotation(): string {
  const now = new Date();
  const nextMonday = new Date(now);
  nextMonday.setDate(now.getDate() + ((1 + 7 - now.getDay()) % 7 || 7));
  nextMonday.setHours(0, 0, 0, 0);
  return nextMonday.toISOString();
}
